module main namespace=main {
  page "Home" id=home {
    main {
      row {
        col md=4 span=6 {
          stack {
            text "Status" size="2xl"
          }
        }
        col span=6 {
          relative h=100 w=200 {
            badge "New" anchor="top-right"
            marker 1 color="blue"
          }
        }
      }
      select "Country" id=country options=[{label="Korea",value="KR"},{label="Japan",value="JP"}] value="KR"
      checkbox "Agree" id=agree checked=true
      radio "Option A" id=a name="choice" value="a"
      switch "Enabled" id=enabled
      slider "Volume" id=volume max=100 min=0 step=1 value=50
      textarea "Note" id=note rows=4
      avatar name="User" size=32 src=true
      image alt="Empty image placeholder"
      placeholder "Image" h=100 w=200
      icon name="home" size="md"
      alert "Review required" variant="warning"
      toast "Draft saved" position="bottom-right" variant="info"
      progress max=100 value=50
      spinner "Loading"
      accordion "Details" {
        text "More"
      }
      tooltip "Help" {
        button "Help" id=help
      }
      list {
        item "Fruit" {
          item "Apple"
        }
      }
      table [["Name","Count"],["A",1],["B",2]] striped=true
      nav {
        group "Main" {
          item "Home" navigate="home"
        }
        divider
      }
      tabs id=tabset active=0 {
        tab "General" id=general {
          text "General content"
        }
        tab "Security" id=security {
          text "Security content"
        }
      }
      breadcrumb [{label="Home"}]
      dropdown id=menu aria="Actions" {
        item "Edit"
        divider
        item "Delete" danger=true
      }
      modal "Confirm" id=confirm {
        text "Continue?"
      }
      drawer "Navigation" id=drawer {
        text "Menu"
      }
      popover "More" id=more {
        text "Additional information"
      }
      annotations {
        item 1 "Information" {
          text "The marker identifies this description."
        }
      }
    }
  }
}
}

